function initVideoPlayer() {

  const videoElement = document.createElement('video');
  videoElement.style.display = 'none';
  videoElement.style.position = 'fixed';
  videoElement.style.top = '50%';
  videoElement.style.left = '50%';
  videoElement.style.transform = 'translate(-50%, -50%)';
  videoElement.style.objectFit = 'cover';

  function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }

  function loadVideo() {
    const videoURL = `https://pinata.brightmoments.io/ipfs/${CID}/${selectedImage}.mp4`;
    videoElement.src = videoURL;
  }

  async function loadVideoHeadless() {
    const videoURL = `https://pinata.brightmoments.io/ipfs/${CID}/${selectedImage}.mp4`;
    const res = await fetch(videoURL);
    const videoBlob = await res.blob();
    const base64Data = await blobToBase64(videoBlob);
    videoElement.src = base64Data;
  }

  videoElement.oncanplaythrough = function() {
    videoElement.style.display = 'block';
  };

  if (!/\bHeadlessChrome/.test(navigator.userAgent)) {
    videoElement.setAttribute('preload', 'auto');
	  loadVideo();
    document.body.appendChild(videoElement);
    document.onclick = function() {
      videoElement.setAttribute('loop', '');
      videoElement.play();
      document.onclick = null;
    };
  } else {
    console.log("in headless context");
    document.body.appendChild(videoElement);
    loadVideoHeadless();
    document.onclick = function() {
      videoElement.setAttribute('loop', '');
      videoElement.play();
      document.onclick = null;
    };
  }
  function adjustVideoSize() {
    if (window.innerWidth > window.innerHeight) {
      videoElement.style.width = 'auto';
      videoElement.style.height = '100vh';
    } else {
      videoElement.style.width = '100vw';
      videoElement.style.height = 'auto';
    }
  }
  adjustVideoSize();
  window.addEventListener('resize', adjustVideoSize);
}

document.addEventListener('DOMContentLoaded', initVideoPlayer);
